var t=`0441-lohikeitto`;var n=`world-0441`;var a=`FI`;var o=`northern-europe`;var s=4;var r=36;var l={en:`Lohikeitto`,ua:`Лохікейтто`};var d={en:`A traditional dish from Finland, centered on leek, potato, salmon, heavy cream. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Фінляндія. Основні складники: цибуля-порей, картопля, лосось, вершки високої жирності. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`leek`,220,`g`],[`unsalted-butter`,35,`g`]]},{en:`Cook the listed ingredients in simmering water for about 17 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 17 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:17,i:[[`potato`,450,`g`],[`water`,700,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 9 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 9 хвилин до готовності й м’якості.`,t:[`poaching`],m:9,i:[[`salmon`,600,`g`],[`heavy-cream`,260,`ml`],[`allspice-berries`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`dill`,22,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:t,id:n,country:`FI`,region:o,servings:4,minutes:36,title:l,text:d,steps:g};export{a as country,u as default,n as id,r as minutes,o as region,s as servings,t as slug,g as steps,d as text,l as title};